#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/code.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Format and lint the uncommitted files (every file with --all), and scan all code"
# MISE dir="."
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--all" help="format and lint every file of this repository, not only the uncommitted files"
# USAGE flag "--debug" help="emit debug logs"

import os
import subprocess
import sys


def run(*cmd):
  """Run the command. When it fails, stop the task with its code."""
  rc = subprocess.run(cmd, check=False).returncode
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  # Each subtask accepts --debug and passes it on to its own subtasks, and
  # code:format and code:lint accept --all; code:sec scans all code.
  flags = ["--debug"] if os.environ.get("usage_debug", "false") == "true" else []
  all_ = ["--all"] if os.environ.get("usage_all", "false") == "true" else []

  run("mise", "run", "code:format", *all_, *flags)

  run("mise", "run", "code:lint", *all_, *flags)

  run("mise", "run", "code:sec", *flags)


if __name__ == "__main__":
  main()
